import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const checkOnly = process.argv.includes("--check");
const root = resolve(import.meta.dirname, "..");
const sharedSourcePath = resolve(root, "packages/shared/src/rpc/contract.ts");
const declarationSourcePath = resolve(root, "packages/shared/out/rpc/contract.d.ts");
const extensionTargetPath = resolve(root, "packages/extension/src/backend/rpc/contract.ts");
const webviewTargetPath = resolve(root, "packages/webview/src/app/rpcContract.generated.d.ts");

const header = "/* This file is generated by pnpm rpc:generate. Do not edit by hand. */";
const sharedSource = await readFile(sharedSourcePath, "utf8");
const declarationSource = await readFile(declarationSourcePath, "utf8");

const generatedExtensionContract = [header, sharedSource.trim(), ""].join("\n");
const generatedWebviewDeclaration = [
  "/* This file is generated by pnpm rpc:generate. Do not edit by hand. */",
  declarationSource.replace(/\n\/\/# sourceMappingURL=.*\.map\s*$/u, "").trim(),
  ""
].join("\n");

if (checkOnly) {
  const currentExtensionContract = await readFile(extensionTargetPath, "utf8");
  const currentWebviewDeclaration = await readFile(webviewTargetPath, "utf8");
  if (currentExtensionContract !== generatedExtensionContract) {
    throw new Error("Extension RPC contract is stale. Run pnpm rpc:generate.");
  }
  if (currentWebviewDeclaration !== generatedWebviewDeclaration) {
    throw new Error("Webview RPC declaration is stale. Run pnpm rpc:generate.");
  }
} else {
  await writeFile(extensionTargetPath, generatedExtensionContract);
  await writeFile(webviewTargetPath, generatedWebviewDeclaration);
}
